import { Component, computed, input } from '@angular/core';

export type HrmGap = 'xs' | 'sm' | 'md' | 'lg' | 'xl';

const GAP: Record<HrmGap, string> = {
  xs: 'var(--space-1)', sm: 'var(--space-2)', md: 'var(--space-4)', lg: 'var(--space-6)', xl: 'var(--space-8)',
};

/** hrm-flex — container flex theo token gap. Thay nz-flex/nz-space (không cần
 *  nzSpaceItem). Dùng: <hrm-flex gap="md" justify="between">...</hrm-flex> */
@Component({
  selector: 'hrm-flex',
  template: `<ng-content />`,
  host: {
    class: 'hrm-flex',
    '[style.display]': '"flex"',
    '[style.flexDirection]': 'direction()',
    '[style.gap]': 'gapValue()',
    '[style.justifyContent]': 'justifyValue()',
    '[style.alignItems]': 'alignValue()',
    '[style.flexWrap]': 'wrap() ? "wrap" : "nowrap"',
  },
})
export class HrmFlex {
  readonly direction = input<'row' | 'column'>('row');
  readonly gap = input<HrmGap>('md');
  readonly justify = input<'start' | 'center' | 'end' | 'between' | 'around'>('start');
  readonly align = input<'start' | 'center' | 'end' | 'stretch'>('center');
  readonly wrap = input(false);

  protected readonly gapValue = computed(() => GAP[this.gap()]);
  protected readonly justifyValue = computed(() => {
    const j = this.justify();
    return j === 'between' ? 'space-between' : j === 'around' ? 'space-around' : `flex-${j === 'start' ? 'start' : j === 'end' ? 'end' : 'center'}`.replace('flex-center', 'center');
  });
  protected readonly alignValue = computed(() => {
    const a = this.align();
    return a === 'stretch' ? 'stretch' : `flex-${a}`.replace('flex-center', 'center');
  });
}

/** hrm-space — alias hrm-flex (khoảng cách giữa item). */
@Component({
  selector: 'hrm-space',
  template: `<ng-content />`,
  host: {
    class: 'hrm-space',
    '[style.display]': '"inline-flex"',
    '[style.flexDirection]': 'direction()',
    '[style.gap]': 'gapValue()',
    '[style.alignItems]': '"center"',
    '[style.flexWrap]': '"wrap"',
  },
})
export class HrmSpace {
  readonly direction = input<'row' | 'column'>('row');
  readonly gap = input<HrmGap>('sm');
  protected readonly gapValue = computed(() => GAP[this.gap()]);
}
